/**
 * Idempotently adds the usage descriptions BeenBy needs to ios/App/App/Info.plist.
 *
 * The Info.plist is generated by `npx cap add ios` and is not checked into git,
 * so this script patches whatever exists locally instead of overwriting it.
 *
 * Run: node scripts/patch-ios-plist.mjs
 */
import { readFileSync, writeFileSync, existsSync } from "node:fs";

const PLIST = "ios/App/App/Info.plist";

const KEYS = {
  NSCameraUsageDescription:
    "BeenBy använder kameran när du vill ta ett foto och dela det i familjechatten.",
  NSPhotoLibraryUsageDescription:
    "BeenBy behöver tillgång till dina bilder när du vill dela ett foto i familjechatten.",
};

if (!existsSync(PLIST)) {
  console.error(`Hittar inte ${PLIST}. Kör "npx cap add ios" först.`);
  process.exit(1);
}

let xml = readFileSync(PLIST, "utf8");
let added = [];

for (const [key, value] of Object.entries(KEYS)) {
  if (xml.includes(`<key>${key}</key>`)) continue;
  xml = xml.replace(
    /<dict>/,
    `<dict>\n\t<key>${key}</key>\n\t<string>${value}</string>`,
  );
  added.push(key);
}

writeFileSync(PLIST, xml);
console.log(added.length ? `Lade till: ${added.join(", ")}` : "Inget att göra – nycklarna finns redan.");
